// Original forward cash comparison. Service is assumed available for the whole common horizon.
export const repairReplaceDefinitions={
 repairReplace:{title:'Compare the cash that changes from today at one common exit date',fields:[
  ['pastPurchase','Original price already paid, unrecoverable (context only; CAD)',2200,0,20000,100],
  ['repairQuote','Repair payment now to retain the old item (CAD)',450,0,5000,50],
  ['replacementPrice','Replacement purchase price now (CAD)',1600,0,20000,100],
  ['installation','Replacement delivery and installation now (CAD)',150,0,5000,50],
  ['currentResale','Net cash from selling the old item now if replacing (CAD)',100,0,10000,50],
  ['annualOld','Annual running cost after repair (CAD)',320,0,5000,20],
  ['annualNew','Annual running cost after replacement (CAD)',180,0,5000,20],
  ['repairEndValue','Net sale value of the repaired item at the common exit (CAD)',0,0,10000,50],
  ['replaceEndValue','Net sale value of the replacement at the common exit (CAD)',400,0,10000,50],
  ['years','Common remaining service and comparison horizon (whole years)',5,1,15,1],
  ['discount','Effective annual nominal discount rate (%)',4,0,15,.5]
 ]}
};
export function repairReplaceCost(input) {
 const n=input.years,r=input.discount/100,discountFactor=(1+r)**(-n),annuity=r===0?n:-Math.expm1(-n*Math.log1p(r))/r;
 const repairStart=input.repairQuote,replaceStart=input.replacementPrice+input.installation-input.currentResale;
 const repairNominal=repairStart+input.annualOld*n-input.repairEndValue,replaceNominal=replaceStart+input.annualNew*n-input.replaceEndValue;
 const repairPV=repairStart+input.annualOld*annuity-input.repairEndValue*discountFactor,replacePV=replaceStart+input.annualNew*annuity-input.replaceEndValue*discountFactor;
 const rows=Array.from({length:n+1},(_,year)=>({x:year,repair:repairStart+input.annualOld*year-(year===n?input.repairEndValue:0),replace:replaceStart+input.annualNew*year-(year===n?input.replaceEndValue:0)}));
 return {annuity,discountFactor,repairStart,replaceStart,repairNominal,replaceNominal,repairPV,replacePV,difference:replacePV-repairPV,rows,initialDifference:replaceStart-repairStart,runningDifferencePV:(input.annualNew-input.annualOld)*annuity,exitDifferencePV:-(input.replaceEndValue-input.repairEndValue)*discountFactor,opportunityRepair:repairStart+input.currentResale,opportunityReplace:input.replacementPrice+input.installation};
}
export function repairReplaceResult(kind,input) {
 if(kind!=='repairReplace')throw Error('Unknown repair-or-replace topic.');
 const p=repairReplaceCost(input);
 return {metrics:[['Present value of future net cost: repair and retain',p.repairPV,'money'],['Present value of future net cost: replace now',p.replacePV,'money'],['Replacement minus repair present cost; negative favours replacement',p.difference,'money']],note:'Original deterministic nominal-CAD illustration. The entered original purchase price of CAD '+input.pastPurchase.toLocaleString('en-CA')+' is already paid and unrecoverable; it is context only and never enters the forward costs. Each option is assumed to provide the same required service throughout the common whole-year horizon, without another failure, replacement or difference in usage. Repair is paid at time zero. Replacement purchase and installation are paid at time zero, less net proceeds from selling the old item at that same time. Running costs are constant nominal amounts paid at each year-end. Each item is sold for its independently entered net value at the common final year-end, after that year’s running cost. No intermediate sale is assumed. Present values use the entered effective annual nominal discount rate; they are alternatives to undiscounted totals, not additional bills. No loan, interest charge, tax calculation, refund, warranty recovery, inflation forecast, service interruption or environmental benefit is modeled. Costs may be negative if entered sale receipts exceed outlays. Changing the past-price context does not change any metric or chart.',charts:[
  {id:'repair-replace-upfront-cash',type:'waterfall',title:'Replacement cash today includes the old item’s current sale proceeds',unit:'money',rows:[{label:'Replacement purchase',value:input.replacementPrice},{label:'Delivery and installation',value:input.installation},{label:'Sell old item now: net proceeds',value:-input.currentResale}],totalLabel:'Net cash cost to replace now',evidence:'Hypothetical forward cash scenarios',note:'The separate repair option pays only the entered repair quote at time zero and retains the old item. Its original purchase payment is not another outflow today. Sale proceeds here must be available on the assumed purchase date; a later sale would need a separate cash bridge. A negative total means a net initial receipt under the entered assumptions, rather than an extra cost.'},
  {id:'repair-replace-cumulative-cash',type:'line',title:'Undiscounted net costs through the common exit date',unit:'money',xLabel:'Years from today · year 0 is the immediate decision',series:[{name:'Repair and retain',rows:p.rows.map(row=>({x:row.x,value:row.repair}))},{name:'Replace now',rows:p.rows.map(row=>({x:row.x,value:row.replace})),dash:true}],evidence:'Hypothetical forward cash scenarios',note:'Each line starts with today’s net cash outlay and adds year-end running costs. Only the final point subtracts the entered exit sale receipt, so a final decline can be a sale effect rather than lower running costs. Connecting segments join discrete year-end observations; they do not imply that bills or sale receipts arrive continuously. Neither line includes the original price already paid. The same end date and required service apply to both alternatives.'},
  {id:'repair-replace-present-cost-bridge',type:'waterfall',title:'Reconcile the replacement-minus-repair present-cost difference',unit:'money',rows:[{label:'Additional cash cost today',value:p.initialDifference},{label:'PV of running-cost change',value:p.runningDifferencePV},{label:'PV of final-sale change',value:p.exitDifferencePV}],totalLabel:'Replacement extra present cost',evidence:'Hypothetical discounted cash scenarios',note:'Positive amounts increase replacement’s cost relative to repair; negative amounts reduce it. The first step already includes today’s old-item sale proceeds and the avoided repair quote. The exit step subtracts replacement sale proceeds less repaired-item sale proceeds, discounted from the same final date. A negative endpoint means lower modeled present cost for replacement, not a guaranteed saving or a financing offer. The bridge adds exactly to the difference between the two headline present values.'},
  {id:'repair-replace-quote-running-matrix',type:'heatmap',title:'Present-cost difference under alternative repair quotes and replacement running costs',unit:'money',signed:true,compactValues:false,columns:[100,200,300,400].map(v=>'$'+v+'/yr'),rows:[0,300,600,900].map(repairQuote=>({label:'Repair $'+repairQuote,values:[100,200,300,400].map(annualNew=>repairReplaceCost({...input,repairQuote,annualNew}).difference)})),evidence:'Hypothetical discounted cash scenarios',note:'Rows replace the repair payment today; columns replace the replacement item’s annual running cost. The horizon, discount rate, old item’s running cost, current net sale proceeds and both final sale values remain selected inputs. Each signed cell is replacement present cost minus repair present cost. These are alternative cases, not repair quotes, reliability probabilities or projected energy prices. A longer assumed life is not inferred from a lower cell value.'}
 ]};
}
